function BrowseView({ screen, params, navigate }: { screen: Screen; params: any; navigate: (screen: Screen, params?: any) => void }) {
  const [filter, setFilter] = useState('All')
  const [search, setSearch] = useState(params?.query || '')
  const config: Record<string, { eyebrow: string; title: string; copy: string }> = {
    categories: { eyebrow: 'DISCOVER MORE', title: 'Browse every category', copy: 'Handpicked local help for life’s everyday needs.' },
    'category-services': { eyebrow: 'CURATED FOR YOU', title: params?.label || 'Home services', copy: 'Explore trusted providers, simple pricing and flexible availability.' },
    'all-services': { eyebrow: 'FIND YOUR MATCH', title: 'All services', copy: 'Search, compare and book—without any guesswork.' },
    providers: { eyebrow: 'THE HELPY STANDARD', title: 'Providers people love', copy: 'Rated highly by neighbours across Qatar.' },
    deals: { eyebrow: 'A LITTLE EXTRA', title: 'Deals worth taking', copy: 'Special prices from providers you already trust.' },
    'offers-events': { eyebrow: 'WHAT’S ON', title: 'Offers & events', copy: 'Limited-time bundles designed around your week.' },
  }
  const current = config[screen] || config['all-services']
  const filters = ['All', ...Array.from(new Set(SERVICES.map(service => service.category)))]
  const categoryLabels: Record<string, string> = { home: 'Home services', cleaning: 'Home services', car: 'Car services', salon: 'Salon & spa', laundry: 'Laundry', maintenance: 'Maintenance', digital: 'Digital', education: 'Education', delivery: 'Deliveries', travel: 'Travel', support: 'Support' }
  const activeCategory = screen === 'category-services' ? categoryLabels[params?.id] || params?.label : filter
  const services = useMemo(() => SERVICES.filter(service => (activeCategory === 'All' || service.category === activeCategory) && `${service.name} ${service.provider} ${service.category}`.toLowerCase().includes(search.toLowerCase())), [activeCategory, search])
  if (screen === 'categories') return <div><PageHeading eyebrow={current.eyebrow} title={current.title} copy={current.copy}/><div className="mt-8 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{CATEGORIES.map(category => <button key={category.id} onClick={() => navigate('category-services', { id: category.id, label: category.label })} className="group relative min-h-[215px] overflow-hidden rounded-[25px] bg-white p-6 text-left shadow-sm ring-1 ring-[#e2ebf7] transition"><div className="absolute right-0 top-0 h-36 w-40 opacity-95"><img src={category.image} alt="" loading="lazy" className="h-full w-full object-contain transition duration-300"/></div><div className="relative flex h-full flex-col justify-end"><span className="w-fit rounded-full bg-blue-50 px-3 py-1 text-[10px] font-black uppercase tracking-wide text-[#0967ff]">{category.count}</span><h2 className="mt-3 text-xl font-black">{category.label}</h2><p className="mt-1 text-sm font-semibold text-[#71809a]">Browse trusted specialists <ArrowRight size={14} className="ml-1 inline text-[#0967ff]"/></p></div></button>)}</div></div>
  return <div><PageHeading eyebrow={current.eyebrow} title={screen === 'category-services' ? `${activeCategory} services` : current.title} copy={current.copy} action={screen === 'deals' ? 'Explore events' : undefined} onAction={() => navigate('offers-events')} /><div className="mt-8 flex flex-col gap-4 rounded-2xl bg-white p-4 shadow-sm ring-1 ring-[#e2ebf7] lg:flex-row lg:items-center"><div className="relative flex-1"><Search size={18} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#8290a9]"/><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Search by service or provider" className="h-11 w-full rounded-xl bg-[#f5f8fd] pl-10 pr-4 text-sm font-semibold outline-none focus:ring-2 focus:ring-blue-100"/></div>{screen !== 'category-services' && <div className="flex max-w-full gap-2 overflow-x-auto">{filters.map(item => <button key={item} onClick={() => setFilter(item)} className={`shrink-0 rounded-xl px-3.5 py-2.5 text-xs font-black transition ${filter === item ? 'bg-[#0967ff] text-white shadow-md shadow-blue-200' : 'bg-[#f5f8fd] text-[#657590] hover:bg-blue-50'}`}>{item}</button>)}</div>}</div>{screen === 'deals' && <div className="mt-6 grid gap-4 md:grid-cols-3"><OfferPanel title="Deep clean, lighter price" text="Save 20% on a fresh-home reset with Scrubs." image="/assets/ai-banner-home-cleaning.jpg" onClick={() => navigate('service-detail', SERVICES[0])}/><OfferPanel title="A little glow goes a long way" text="Beauty day packages from QAR 120." image="/assets/ai-banner-glow-salon.jpg" onClick={() => navigate('service-detail', SERVICES[6])}/><OfferPanel title="Car care, on your schedule" text="Premium washes from QAR 75." image="/assets/ai-banner-sparkle-carwash.jpg" onClick={() => navigate('service-detail', SERVICES[3])}/></div>}<p className="mt-6 text-sm font-bold text-[#75839d]">{services.length} services available</p><div className="mt-4 grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{services.map(service => <ServiceCard key={service.id} service={service} navigate={navigate}/>)}</div>{services.length === 0 && <EmptyScreen title="No services matched that search" body="Try another term or clear a filter to see more providers." onClick={() => { setSearch(''); setFilter('All') }} action="Clear filters"/>}</div>
}

function ServiceDetailView({ service, navigate }: { service: Service; navigate: (screen: Screen, params?: any) => void }) {
  const [date, setDate] = useState('Today')
  const [time, setTime] = useState('10:00 AM')
  const dates = ['Today', 'Tomorrow', 'Wed, 10', 'Thu, 11', 'Fri, 12']
  const times = ['08:00 AM', '10:00 AM', '12:00 PM', '02:00 PM', '04:00 PM', '06:00 PM']
  return <div className="grid gap-7 xl:grid-cols-[1.25fr_.75fr]"><div><div className="relative overflow-hidden rounded-[30px] bg-[#102044]"><img src={service.heroImg || service.image} alt="" className="h-[310px] w-full object-cover opacity-90 sm:h-[390px]"/><div className="absolute inset-0 bg-gradient-to-t from-[#061331]/80 via-transparent to-transparent"/><button onClick={() => navigate('favorites')} className="absolute right-5 top-5 flex h-11 w-11 items-center justify-center rounded-xl bg-white/90 text-[#102044] shadow-lg"><Heart size={19}/></button><div className="absolute inset-x-7 bottom-7 text-white"><span className="rounded-full bg-white/15 px-3 py-1 text-xs font-black backdrop-blur">{service.category}</span><h1 className="mt-3 text-3xl font-black tracking-[-.04em] sm:text-4xl">{service.name}</h1><p className="mt-1 text-sm font-bold text-blue-100">by {service.provider}</p></div></div><div className="mt-7 rounded-[26px] bg-white p-6 shadow-sm ring-1 ring-[#e2ebf7]"><div className="flex flex-wrap items-center gap-4 border-b border-[#e9eff8] pb-6"><div className="flex items-center gap-1 text-sm font-black text-amber-500"><Star size={17} fill="currentColor"/>{service.rating}<span className="ml-1 font-bold text-[#75839d]">({service.reviews} reviews)</span></div><span className="h-1 w-1 rounded-full bg-[#c1cbdb]"/><span className="text-sm font-bold text-[#75839d]"><ShieldCheck size={16} className="mr-1 inline text-[#0967ff]"/>Verified provider</span><span className="h-1 w-1 rounded-full bg-[#c1cbdb]"/><span className="text-sm font-bold text-[#75839d]"><Clock3 size={16} className="mr-1 inline text-[#0967ff]"/>Usually replies in minutes</span></div><h2 className="mt-6 text-xl font-black">About this service</h2><p className="mt-3 max-w-2xl leading-7 text-[#687792]">{service.description}</p><div className="mt-7 grid gap-3 sm:grid-cols-3"><DetailCheck title="What’s included" text="Professional service and essential supplies"/><DetailCheck title="Before we arrive" text="Tell us anything that will help"/><DetailCheck title="Our promise" text="Support is always a message away"/></div><button onClick={() => navigate('reviews', service)} className="mt-6 text-sm font-black text-[#0967ff]">Read provider reviews <ArrowRight size={15} className="ml-1 inline"/></button></div></div><aside className="h-fit rounded-[26px] bg-white p-6 shadow-sm ring-1 ring-[#e2ebf7] xl:sticky xl:top-24"><div className="flex items-start justify-between"><div><p className="text-xs font-black uppercase tracking-[.14em] text-[#0967ff]">Book a time</p><h2 className="mt-1 text-2xl font-black">From QAR {service.price}</h2></div><span className="rounded-xl bg-[#ecf5ff] px-3 py-2 text-xs font-black text-[#0967ff]">No surprise fees</span></div><p className="mt-5 text-sm font-black">Select a day</p><div className="mt-3 grid grid-cols-5 gap-2">{dates.map(item => <button key={item} onClick={() => setDate(item)} className={`rounded-xl px-1 py-3 text-center text-xs font-black transition ${date === item ? 'bg-[#0967ff] text-white' : 'bg-[#f4f8fe] text-[#60708c] hover:bg-blue-50'}`}>{item}</button>)}</div><p className="mt-6 text-sm font-black">Available times</p><div className="mt-3 grid grid-cols-2 gap-2">{times.map(item => <button key={item} onClick={() => setTime(item)} className={`rounded-xl py-2.5 text-xs font-black transition ${time === item ? 'bg-[#0967ff] text-white' : 'bg-[#f4f8fe] text-[#60708c] hover:bg-blue-50'}`}>{item}</button>)}</div><button onClick={() => navigate('booking-checkout', { ...service, date, time })} className="mt-6 h-13 w-full rounded-xl bg-[#0967ff] py-3.5 text-sm font-black text-white shadow-lg shadow-blue-200 transition hover:bg-[#0759df]">Continue to booking <ArrowRight size={16} className="ml-1 inline"/></button><p className="mt-3 text-center text-[11px] font-bold text-[#91a0b7]">Free cancellation before your provider confirms.</p></aside></div>
}

function DesktopCheckoutFlow({ service, initialAddress, navigate }: { service: Service & { date?: string; time?: string }; initialAddress?: string; navigate: (screen: Screen, params?: any) => void }) {
  const { addBooking } = useNav()
  const [address, setAddress] = useState(initialAddress || 'Home · West Bay, Doha')
  const [paymentMethod, setPaymentMethod] = useState<'card' | 'apple' | 'google' | 'new'>('card')
  const [showPayment, setShowPayment] = useState(false)
  const [cardNumber, setCardNumber] = useState('')
  const [expiry, setExpiry] = useState('')
  const [cvv, setCvv] = useState('')
  const [processing, setProcessing] = useState(false)
  const paymentLabel = paymentMethod === 'apple' ? 'Apple Pay' : paymentMethod === 'google' ? 'Google Pay' : paymentMethod === 'new' ? `•••• ${cardNumber.replace(/\D/g, '').slice(-4) || '0000'}` : 'Visa •••• 4821'
  const canPay = paymentMethod !== 'new' || (cardNumber.replace(/\D/g, '').length >= 12 && expiry.length >= 5 && cvv.length >= 3)
  const completeBooking = () => {
    if (!canPay || processing) return
    setProcessing(true)
    window.setTimeout(() => {
      const booking = { ...service, id: `HLP-${Date.now().toString().slice(-5)}`, status: 'Confirmed', addressLabel: address, paymentMethod: paymentLabel }
      addBooking({ id: booking.id, provider: service.provider, service: service.name, date: service.date || 'Tomorrow', time: service.time || '10:00 AM', price: service.price, status: 'Confirmed', providerBg: service.providerBg, providerEmoji: service.providerEmoji, providerImage: service.providerImage, addressLabel: address })
      navigate('booking-success', booking)
    }, 950)
  }
  return <div>
    <PageHeading eyebrow="SECURE CHECKOUT" title="Review and confirm" copy="Everything is clear before you pay. Your provider only receives the booking details after confirmation."/>
    <div className="mt-8 grid gap-7 xl:grid-cols-[1.15fr_.85fr]">
      <div className="space-y-5">
        <CheckoutBlock number="01" title="Service location" action="Manage locations" onAction={() => navigate('location', { returnTo: 'booking-checkout', booking: service, addressLabel: address })}>
          <div className="grid gap-3 sm:grid-cols-2">{['Home · West Bay, Doha', 'Work · Lusail Boulevard'].map(item => <button key={item} onClick={() => setAddress(item)} className={`rounded-2xl border p-4 text-left transition ${address === item ? 'border-[#0967ff] bg-[#f3f8ff] ring-2 ring-blue-100' : 'border-[#e2eaf5] hover:border-blue-200'}`}><MapPin size={18} className={address === item ? 'text-[#0967ff]' : 'text-[#8290a9]'}/><p className="mt-2 text-sm font-black">{item.split(' · ')[0]}</p><p className="mt-1 text-xs font-bold text-[#7d8ba4]">{item.split(' · ')[1]}</p></button>)}</div>
          <button onClick={() => navigate('location', { returnTo: 'booking-checkout', booking: service, addressLabel: address })} className="mt-4 inline-flex items-center gap-2 text-xs font-black text-[#0967ff]"><Plus size={14}/> Add or pin a new location</button>
        </CheckoutBlock>
        <CheckoutBlock number="02" title="Payment method" action="Edit payment" onAction={() => setShowPayment(true)}>
          <button onClick={() => setShowPayment(true)} className="flex w-full items-center gap-3 rounded-2xl bg-[#f5f8fd] p-4 text-left transition hover:bg-[#edf5ff]"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-white text-[#0967ff] shadow-sm"><CreditCard size={20}/></div><div className="flex-1"><p className="text-sm font-black">{paymentLabel}</p><p className="mt-1 text-xs font-bold text-[#7d8ba4]">Encrypted and securely processed</p></div><ChevronRight size={18} className="text-[#8c9ab0]"/></button>
        </CheckoutBlock>
        <CheckoutBlock number="03" title="Helpful notes"><textarea placeholder="Access instructions, preferences, or anything useful for your provider…" className="h-28 w-full resize-none rounded-2xl bg-[#f5f8fd] p-4 text-sm font-semibold outline-none placeholder:text-[#9aa7bc] focus:ring-2 focus:ring-blue-100" /></CheckoutBlock>
      </div>
      <aside className="h-fit rounded-[26px] bg-[#071b52] p-6 text-white shadow-xl shadow-blue-200 xl:sticky xl:top-24"><p className="text-xs font-black uppercase tracking-[.14em] text-[#8fd0ff]">Booking summary</p><div className="mt-5 flex gap-3"><img src={service.heroImg || service.image} alt="" className="h-16 w-16 rounded-2xl object-cover"/><div><p className="text-base font-black">{service.name}</p><p className="mt-1 text-sm font-bold text-blue-100">{service.provider}</p><p className="mt-2 text-xs font-bold text-[#9ed7ff]"><CalendarDays size={13} className="mr-1 inline"/>{service.date || 'Tomorrow'} · {service.time || '10:00 AM'}</p></div></div><div className="my-6 border-t border-white/15"/><div className="space-y-3 text-sm font-bold text-blue-100">{service.selectedServices?.map(item => <div key={item.label} className="flex justify-between gap-4"><span>{item.label}</span><span className="shrink-0">QAR {item.price}</span></div>)}{service.extras?.map(item => <div key={item.label} className="flex justify-between gap-4 text-xs text-blue-200"><span>{item.label}</span><span className="shrink-0">+ QAR {item.price}</span></div>)}{!service.selectedServices?.length && <div className="flex justify-between"><span>Service</span><span>QAR {service.price}</span></div>}<div className="flex justify-between"><span>Booking fee</span><span>QAR 0</span></div><div className="flex justify-between border-t border-white/15 pt-4 text-base font-black text-white"><span>Total</span><span>QAR {service.price}</span></div></div><button onClick={() => setShowPayment(true)} className="mt-6 w-full rounded-xl bg-white py-3.5 text-sm font-black text-[#0967ff] transition hover:bg-blue-50">Continue to payment <ArrowRight size={16} className="ml-1 inline"/></button><p className="mt-3 text-center text-[11px] font-bold text-blue-200">Free cancellation before your provider confirms.</p></aside>
    </div>
    {showPayment && <div className="fixed inset-0 z-[70] flex items-end justify-center bg-[#071331]/55 p-0 backdrop-blur-sm sm:items-center sm:p-6" role="dialog" aria-modal="true" aria-label="Choose payment method"><button onClick={() => !processing && setShowPayment(false)} className="absolute inset-0" aria-label="Close payment"/><section className="relative w-full max-w-[560px] rounded-t-[30px] bg-white p-6 shadow-2xl sm:rounded-[30px]"><div className="mx-auto mb-5 h-1.5 w-12 rounded-full bg-[#d9e2ef] sm:hidden"/><div className="flex items-start justify-between"><div><p className="text-xs font-black uppercase tracking-[.14em] text-[#0967ff]">Secure payment</p><h2 className="mt-1 text-2xl font-black">Pay QAR {service.price}</h2><p className="mt-2 text-sm font-semibold text-[#70809a]">Choose how you’d like to pay for this booking.</p></div><button onClick={() => !processing && setShowPayment(false)} className="hidden rounded-xl bg-[#f4f7fc] p-2 text-[#65738d] sm:block"><X size={19}/></button></div><div className="mt-6 grid grid-cols-3 gap-3">{([{ id: 'card', label: 'Visa •••• 4821', icon: <CreditCard size={18}/> }, { id: 'apple', label: 'Apple Pay', icon: <span className="text-lg font-black"></span> }, { id: 'google', label: 'Google Pay', icon: <span className="font-black text-[#4285f4]">G</span> }] as const).map(method => <button key={method.id} onClick={() => setPaymentMethod(method.id)} className={`rounded-2xl border p-3 text-left transition ${paymentMethod === method.id ? 'border-[#0967ff] bg-[#f3f8ff] ring-2 ring-blue-100' : 'border-[#e2eaf5] hover:border-blue-200'}`}><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-white text-[#0967ff] shadow-sm">{method.icon}</span><p className="mt-3 text-xs font-black">{method.label}</p></button>)}</div><button onClick={() => setPaymentMethod('new')} className={`mt-3 flex w-full items-center gap-3 rounded-2xl border p-4 text-left transition ${paymentMethod === 'new' ? 'border-[#0967ff] bg-[#f3f8ff] ring-2 ring-blue-100' : 'border-[#e2eaf5] hover:border-blue-200'}`}><Plus size={18} className="text-[#0967ff]"/><span className="text-sm font-black">Pay with a new card</span></button>{paymentMethod === 'new' && <div className="mt-4 grid gap-3 rounded-2xl bg-[#f5f8fd] p-4 sm:grid-cols-2"><input value={cardNumber} onChange={event => setCardNumber(event.target.value.replace(/\D/g, '').slice(0,16).replace(/(.{4})/g, '$1 ').trim())} inputMode="numeric" placeholder="Card number" className="h-12 rounded-xl bg-white px-4 text-sm font-bold outline-none ring-1 ring-[#e0e8f5] focus:ring-2 focus:ring-blue-200 sm:col-span-2"/><input value={expiry} onChange={event => setExpiry(event.target.value.replace(/\D/g, '').slice(0,4).replace(/(.{2})/, '$1/'))} inputMode="numeric" placeholder="MM/YY" className="h-12 rounded-xl bg-white px-4 text-sm font-bold outline-none ring-1 ring-[#e0e8f5] focus:ring-2 focus:ring-blue-200"/><input value={cvv} onChange={event => setCvv(event.target.value.replace(/\D/g, '').slice(0,4))} inputMode="numeric" placeholder="CVV" className="h-12 rounded-xl bg-white px-4 text-sm font-bold outline-none ring-1 ring-[#e0e8f5] focus:ring-2 focus:ring-blue-200"/></div>}<button disabled={!canPay || processing} onClick={completeBooking} className="mt-6 h-14 w-full rounded-2xl bg-[#0967ff] text-sm font-black text-white shadow-lg shadow-blue-200 transition hover:bg-[#0759df] disabled:cursor-not-allowed disabled:opacity-50">{processing ? 'Processing payment…' : `Pay QAR ${service.price} securely`} <ShieldCheck size={17} className="ml-1 inline"/></button></section></div>}
  </div>
}

function CheckoutView({ service, navigate }: { service: Service & { date?: string; time?: string }; navigate: (screen: Screen, params?: any) => void }) {
  const [address, setAddress] = useState('Home · West Bay, Doha')
  const [payment, setPayment] = useState('Card ending 4821')
  return <div><PageHeading eyebrow="ONE LAST STEP" title="Confirm your booking" copy="Review your service, choose the details that work for you, and you’re all set."/><div className="mt-8 grid gap-7 xl:grid-cols-[1.15fr_.85fr]"><div className="space-y-5"><CheckoutBlock number="01" title="Where should we come?" action="Manage addresses" onAction={() => navigate('addresses')}><div className="grid gap-3 sm:grid-cols-2">{['Home · West Bay, Doha', 'Work · Lusail Boulevard'].map(item => <button key={item} onClick={() => setAddress(item)} className={`rounded-2xl border p-4 text-left transition ${address === item ? 'border-[#0967ff] bg-[#f3f8ff] ring-2 ring-blue-100' : 'border-[#e2eaf5] hover:border-blue-200'}`}><MapPin size={18} className={address === item ? 'text-[#0967ff]' : 'text-[#8290a9]'}/><p className="mt-2 text-sm font-black">{item.split(' · ')[0]}</p><p className="mt-1 text-xs font-bold text-[#7d8ba4]">{item.split(' · ')[1]}</p></button>)}</div><button onClick={() => navigate('location')} className="mt-3 inline-flex items-center gap-2 text-xs font-black text-[#0967ff]"><Plus size={14}/> Add another address</button></CheckoutBlock><CheckoutBlock number="02" title="Payment" action="Wallet" onAction={() => navigate('wallet')}><div className="flex items-center gap-3 rounded-2xl bg-[#f5f8fd] p-4"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-white text-[#0967ff] shadow-sm"><CreditCard size={19}/></div><div className="flex-1"><p className="text-sm font-black">{payment}</p><p className="text-xs font-bold text-[#7d8ba4]">Securely saved in your wallet</p></div><button onClick={() => setPayment(payment.startsWith('Card') ? 'Apple Pay' : 'Card ending 4821')} className="text-xs font-black text-[#0967ff]">Change</button></div></CheckoutBlock><CheckoutBlock number="03" title="Anything we should know?"><textarea placeholder="Add access notes, preferences, or anything useful for your provider…" className="h-28 w-full resize-none rounded-2xl bg-[#f5f8fd] p-4 text-sm font-semibold outline-none placeholder:text-[#9aa7bc] focus:ring-2 focus:ring-blue-100" /></CheckoutBlock></div><aside className="h-fit rounded-[26px] bg-[#071b52] p-6 text-white shadow-xl shadow-blue-200 xl:sticky xl:top-24"><p className="text-xs font-black uppercase tracking-[.14em] text-[#8fd0ff]">Booking summary</p><div className="mt-5 flex gap-3"><img src={service.heroImg || service.image} alt="" className="h-16 w-16 rounded-2xl object-cover"/><div><p className="text-base font-black">{service.name}</p><p className="mt-1 text-sm font-bold text-blue-100">{service.provider}</p><p className="mt-2 text-xs font-bold text-[#9ed7ff]"><CalendarDays size={13} className="mr-1 inline"/>{service.date || 'Tomorrow'} · {service.time || '10:00 AM'}</p></div></div><div className="my-6 border-t border-white/15"/><div className="space-y-3 text-sm font-bold text-blue-100"><div className="flex justify-between"><span>Service</span><span>QAR {service.price}</span></div><div className="flex justify-between"><span>Booking fee</span><span>QAR 0</span></div><div className="flex justify-between border-t border-white/15 pt-4 text-base font-black text-white"><span>Total</span><span>QAR {service.price}</span></div></div><button onClick={() => navigate('booking-success', { ...service, addressLabel: address, status: 'Confirmed', id: `HLP-${Date.now().toString().slice(-5)}` })} className="mt-6 w-full rounded-xl bg-white py-3.5 text-sm font-black text-[#0967ff] transition hover:bg-blue-50">Confirm booking <Check size={16} className="ml-1 inline"/></button><p className="mt-3 text-center text-[11px] font-bold text-blue-200">By confirming, you accept our booking terms.</p></aside></div></div>
}

function BookingSuccessView({ params, navigate }: { params: any; navigate: (screen: Screen, params?: any) => void }) {
  const service = asService(params)
  return <div className="mx-auto max-w-[900px] py-4"><div className="relative overflow-hidden rounded-[32px] bg-[#071b52] px-6 py-12 text-center text-white shadow-2xl shadow-blue-200 sm:px-12"><div className="absolute inset-0 opacity-80" style={{ backgroundImage: 'radial-gradient(circle at 20% 10%,#1e8fff 0,transparent 25%),radial-gradient(circle at 80% 85%,#1bd6b7 0,transparent 23%)' }}/><div className="relative"><div className="mx-auto flex h-20 w-20 items-center justify-center rounded-[26px] bg-white text-[#14ad96] shadow-xl"><CheckCircle2 size={43}/></div><p className="mt-7 text-sm font-black uppercase tracking-[.16em] text-[#aee7ff]">Booking confirmed</p><h1 className="mt-2 text-4xl font-black tracking-[-.05em] sm:text-5xl">You’re all set.</h1><p className="mx-auto mt-4 max-w-lg text-blue-100">{service.provider} has your request. We’ll keep you posted as they confirm the details.</p></div></div><div className="-mt-8 relative mx-4 rounded-[26px] bg-white p-6 shadow-xl ring-1 ring-[#e2ebf7] sm:mx-10 sm:p-8"><div className="flex flex-col gap-5 sm:flex-row sm:items-center"><img src={service.providerImage || service.image} alt="" className="h-16 w-16 rounded-2xl object-cover"/><div className="flex-1"><p className="text-xl font-black">{service.name}</p><p className="mt-1 text-sm font-bold text-[#71809a]">with {service.provider}</p></div><span className="w-fit rounded-full bg-emerald-50 px-3 py-1.5 text-xs font-black text-emerald-600">Confirmed</span></div><div className="mt-7 grid gap-3 border-t border-[#edf1f7] pt-6 sm:grid-cols-3"><SummaryInfo icon={<CalendarDays size={18}/>} label="When" value={`${params?.date || 'Tomorrow'} · ${params?.time || '10:00 AM'}`}/><SummaryInfo icon={<MapPin size={18}/>} label="Where" value={params?.addressLabel || 'Home · West Bay'}/><SummaryInfo icon={<FileText size={18}/>} label="Booking ID" value={params?.id || 'HLP-20841'}/></div><div className="mt-7 flex flex-col gap-3 sm:flex-row"><button onClick={() => navigate('orders')} className="flex-1 rounded-xl bg-[#0967ff] py-3.5 text-sm font-black text-white">View my booking</button><button onClick={() => navigate('chat-thread', { name: service.provider, providerImage: service.providerImage })} className="flex-1 rounded-xl border border-[#d9e5f6] py-3.5 text-sm font-black text-[#0967ff]">Message provider</button></div></div></div>
}

function OrdersView({ screen, params, navigate }: { screen: Screen; params: any; navigate: (screen: Screen, params?: any) => void }) {
  const orders = [{ id: 'HLP-20841', service: SERVICES[0], date: 'Fri, 12 Sept · 10:00 AM', status: 'Confirmed', address: 'Home · West Bay' }, { id: 'HLP-20762', service: SERVICES[1], date: 'Sat, 06 Sept · 2:00 PM', status: 'Completed', address: 'Home · West Bay' }, { id: 'HLP-20509', service: SERVICES[3], date: 'Tue, 26 Aug · 9:00 AM', status: 'Completed', address: 'Work · Lusail' }]
  const selected = screen === 'order-detail' ? { ...orders[0], ...params, service: asService(params) } : null
  if (selected) return <div><PageHeading eyebrow="BOOKING DETAILS" title={selected.service.name} copy={`With ${selected.service.provider}`}/><div className="mt-8 grid gap-7 xl:grid-cols-[1.1fr_.9fr]"><div className="rounded-[26px] bg-white p-7 shadow-sm ring-1 ring-[#e2ebf7]"><div className="flex items-center justify-between"><h2 className="text-xl font-black">Booking timeline</h2><StatusBadge status={selected.status}/></div><div className="mt-7 space-y-0">{[['Booked', 'Your booking was placed successfully.'], ['Confirmed', 'Your provider confirmed the scheduled time.'], ['Upcoming', 'We’ll notify you when your provider is on the way.']].map(([title, detail], index) => <div key={title} className="relative flex gap-4 pb-7 last:pb-0"><div className="relative z-10 flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-blue-50 text-[#0967ff]"><Check size={15}/></div>{index < 2 && <div className="absolute left-[15px] top-8 h-[calc(100%-18px)] w-px bg-blue-100"/>}<div><p className="text-sm font-black">{title}</p><p className="mt-1 text-sm leading-6 text-[#72809a]">{detail}</p></div></div>)}</div></div><div className="rounded-[26px] bg-[#f7faff] p-7 ring-1 ring-[#e2ebf7]"><h2 className="text-xl font-black">Need help?</h2><p className="mt-2 text-sm leading-6 text-[#71809a]">Message your provider directly, or contact the Helpy support team.</p><button onClick={() => navigate('chat-thread', { name: selected.service.provider, providerImage: selected.service.providerImage })} className="mt-5 w-full rounded-xl bg-[#0967ff] py-3 text-sm font-black text-white">Message provider</button><button onClick={() => navigate('contact-us')} className="mt-3 w-full rounded-xl border border-[#dbe6f6] py-3 text-sm font-black text-[#0967ff]">Contact support</button></div></div></div>
  return <div><PageHeading eyebrow="YOUR SCHEDULE" title="My bookings" copy="Keep track of what’s coming up and revisit past appointments." action="Book a service" onAction={() => navigate('all-services')}/><div className="mt-8 overflow-hidden rounded-[26px] bg-white shadow-sm ring-1 ring-[#e2ebf7]"><div className="hidden grid-cols-[1.4fr_1fr_1fr_.7fr] gap-4 border-b border-[#eaf0f8] px-6 py-4 text-[10px] font-black uppercase tracking-[.14em] text-[#95a2b8] md:grid"><span>Service</span><span>When</span><span>Where</span><span>Status</span></div>{orders.map(order => <button key={order.id} onClick={() => navigate('order-detail', order)} className="grid w-full gap-4 border-b border-[#eef2f8] px-5 py-5 text-left transition last:border-0 hover:bg-[#f9fbff] md:grid-cols-[1.4fr_1fr_1fr_.7fr] md:px-6"><div className="flex items-center gap-3"><img src={order.service.providerImage || order.service.image} alt="" className="h-12 w-12 rounded-xl object-cover"/><div><p className="text-sm font-black">{order.service.name}</p><p className="mt-1 text-xs font-bold text-[#75839b]">{order.service.provider}</p></div></div><p className="self-center text-sm font-bold text-[#63718a]">{order.date}</p><p className="self-center text-sm font-bold text-[#63718a]">{order.address}</p><div className="self-center"><StatusBadge status={order.status}/></div></button>)}</div></div>
}

function ChatView({ screen, params, navigate }: { screen: Screen; params: any; navigate: (screen: Screen, params?: any) => void }) {
  const conversations = [{ name: 'Scrubs Cleaning', image: '/assets/scrubs-leaf-logo-clean.png', message: 'We’re looking forward to Friday!', time: '10:24 AM', online: true }, { name: 'Sparkle Auto Wash', image: '/assets/ai-profile-sparkle-carwash.jpg', message: 'Your appointment is complete.', time: 'Yesterday', online: false }, { name: 'Helpy Support', image: '/assets/ai-avatar-support.jpg', message: 'How can we help today?', time: 'Mon', online: true }]
  const [active, setActive] = useState(params?.name || conversations[0].name)
  const [message, setMessage] = useState('')
  const [messages, setMessages] = useState([{ body: 'Hi Siraj! We’re looking forward to Friday’s cleaning.', fromMe: false, time: '10:24 AM' }, { body: 'Thank you! Please ring the bell when you arrive.', fromMe: true, time: '10:26 AM' }, { body: 'Absolutely. We’ll see you at 10:00 AM.', fromMe: false, time: '10:27 AM' }])
  const send = () => { if (!message.trim()) return; setMessages(current => [...current, { body: message.trim(), fromMe: true, time: 'Now' }]); setMessage('') }
  return <div><PageHeading eyebrow="STAY IN THE LOOP" title={screen === 'chat-thread' ? active : 'Messages'} copy={screen === 'chat-thread' ? 'Your conversation is private and secure.' : 'Providers and Helpy support are only a message away.'}/><div className="mt-8 grid min-h-[610px] overflow-hidden rounded-[26px] bg-white shadow-sm ring-1 ring-[#e2ebf7] md:grid-cols-[300px_1fr]"><div className={`${screen === 'chat-thread' ? 'hidden md:block' : ''} border-r border-[#e9eff7] p-4`}><div className="relative"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8492aa]"/><input placeholder="Search messages" className="h-10 w-full rounded-xl bg-[#f5f8fd] pl-9 pr-3 text-xs font-bold outline-none"/></div><div className="mt-4 space-y-1">{conversations.map(conversation => <button key={conversation.name} onClick={() => { setActive(conversation.name); navigate('chat-thread', { name: conversation.name, providerImage: conversation.image }) }} className={`flex w-full items-center gap-3 rounded-xl p-3 text-left transition ${active === conversation.name ? 'bg-blue-50' : 'hover:bg-[#f8faff]'}`}><div className="relative"><img src={conversation.image} alt="" className="h-11 w-11 rounded-xl object-cover"/>{conversation.online && <span className="absolute -right-1 -top-1 h-3 w-3 rounded-full bg-emerald-400 ring-2 ring-white"/>}</div><div className="min-w-0 flex-1"><div className="flex justify-between gap-2"><p className="truncate text-sm font-black">{conversation.name}</p><span className="text-[10px] font-bold text-[#91a0b6]">{conversation.time}</span></div><p className="mt-1 truncate text-xs font-semibold text-[#77859d]">{conversation.message}</p></div></button>)}</div></div><div className="flex min-h-[500px] flex-col"><div className="flex items-center gap-3 border-b border-[#e9eff7] px-5 py-4"><button onClick={() => navigate('chat')} className="md:hidden"><ArrowLeft size={19}/></button><div className="flex h-10 w-10 items-center justify-center overflow-hidden rounded-xl bg-blue-50"><img src={conversations.find(item => item.name === active)?.image} alt="" className="h-full w-full object-cover"/></div><div><p className="text-sm font-black">{active}</p><p className="text-xs font-bold text-emerald-500">Typically replies in minutes</p></div><button onClick={() => navigate('order-detail')} className="ml-auto text-xs font-black text-[#0967ff]">View booking</button></div><div className="flex-1 space-y-5 bg-[#fbfcff] p-5">{messages.map((item, index) => <div key={index} className={`flex ${item.fromMe ? 'justify-end' : 'justify-start'}`}><div className={`max-w-[80%] rounded-2xl px-4 py-3 text-sm font-semibold leading-6 ${item.fromMe ? 'rounded-br-md bg-[#0967ff] text-white' : 'rounded-bl-md bg-white text-[#465573] shadow-sm ring-1 ring-[#e7edf7]'}`}><p>{item.body}</p><p className={`mt-1 text-[10px] font-bold ${item.fromMe ? 'text-blue-100' : 'text-[#98a5b8]'}`}>{item.time}</p></div></div>)}</div><div className="border-t border-[#e9eff7] p-4"><div className="flex gap-2 rounded-2xl bg-[#f4f8fe] p-2"><input value={message} onChange={event => setMessage(event.target.value)} onKeyDown={event => event.key === 'Enter' && send()} placeholder="Write a message…" className="h-10 min-w-0 flex-1 bg-transparent px-3 text-sm font-semibold outline-none"/><button onClick={send} className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#0967ff] text-white"><Send size={16}/></button></div></div></div></div></div>
}

function DesktopLocationFlow({ params, navigate }: { params: any; navigate: (screen: Screen, params?: any) => void }) {
  const [selected, setSelected] = useState(params?.addressLabel || 'Home · West Bay, Doha')
  const [mode, setMode] = useState<'saved' | 'pin' | 'details'>('saved')
  const [placeName, setPlaceName] = useState('')
  const [notes, setNotes] = useState('')
  const savedPlaces = [{ label: 'Home', address: 'Home · West Bay, Doha', detail: 'Tower 19, West Bay' }, { label: 'Work', address: 'Work · Lusail Boulevard', detail: 'Lusail Boulevard, Doha' }, { label: 'Apartment', address: 'Apartment · The Pearl', detail: 'Viva Bahriya 10, The Pearl' }]
  const finish = (address: string) => {
    if (params?.returnTo === 'booking-checkout') navigate('booking-checkout', { booking: params.booking, addressLabel: address })
    else navigate('profile')
  }
  if (mode === 'details') return <div><PageHeading eyebrow="ONE LAST DETAIL" title="Save this location" copy="Give this place a clear name and leave any arrival notes for your provider."/><div className="mx-auto mt-8 max-w-2xl rounded-[28px] bg-white p-6 shadow-sm ring-1 ring-[#e2ebf7] sm:p-8"><div className="flex items-center gap-3 rounded-2xl bg-[#f3f8ff] p-4"><MapPin size={20} className="text-[#0967ff]"/><div><p className="text-sm font-black">{selected}</p><p className="mt-1 text-xs font-bold text-[#73819a]">Pin placed on the map</p></div></div><label className="mt-6 block text-sm font-black">Name this place<input value={placeName} onChange={event => setPlaceName(event.target.value)} placeholder="e.g. Home, Office, Mum’s house" className="mt-2 h-13 w-full rounded-xl bg-[#f5f8fd] px-4 text-sm font-bold outline-none ring-1 ring-[#e1eaf5] focus:ring-2 focus:ring-blue-200"/></label><label className="mt-5 block text-sm font-black">Arrival notes <span className="font-semibold text-[#8a98ad]">(optional)</span><textarea value={notes} onChange={event => setNotes(event.target.value)} placeholder="Building, floor, gate, parking or reception instructions" className="mt-2 h-28 w-full resize-none rounded-xl bg-[#f5f8fd] p-4 text-sm font-semibold outline-none ring-1 ring-[#e1eaf5] focus:ring-2 focus:ring-blue-200"/></label><div className="mt-7 flex gap-3"><button onClick={() => setMode('pin')} className="flex-1 rounded-xl border border-[#dbe6f4] py-3.5 text-sm font-black text-[#53617a]">Back to map</button><button onClick={() => finish(placeName.trim() ? `${placeName.trim()} · ${selected.split(' · ').slice(-1)[0]}` : selected)} className="flex-1 rounded-xl bg-[#0967ff] py-3.5 text-sm font-black text-white shadow-lg shadow-blue-200">Save location <Check size={16} className="ml-1 inline"/></button></div></div></div>
  if (mode === 'pin') return <div><PageHeading eyebrow="PIN YOUR PLACE" title="Choose the exact location" copy="Drag around the map or select a nearby area. You can add building details next."/><div className="mt-8 overflow-hidden rounded-[30px] bg-[#dceeff] shadow-sm ring-1 ring-[#dbe7f4]"><div className="relative h-[440px] overflow-hidden"><img src="/assets/qatar-map-helpy-theme.png" alt="Map of Doha" className="h-full w-full object-cover"/><div className="absolute inset-0 bg-gradient-to-t from-[#053470]/20 via-transparent to-white/10"/><div className="absolute left-1/2 top-1/2 flex h-16 w-16 -translate-x-1/2 -translate-y-full items-center justify-center rounded-full bg-[#0967ff] text-white shadow-2xl shadow-blue-500/50 ring-8 ring-white/80"><MapPin size={30} fill="currentColor"/></div><div className="absolute bottom-5 left-5 right-5 rounded-2xl bg-white/95 p-4 shadow-xl backdrop-blur"><p className="text-xs font-black uppercase tracking-[.13em] text-[#0967ff]">Selected pin</p><div className="mt-2 flex flex-col gap-3 sm:flex-row sm:items-center"><input value={selected} onChange={event => setSelected(event.target.value)} className="h-11 flex-1 rounded-xl bg-[#f4f8fd] px-3 text-sm font-bold outline-none ring-1 ring-[#deebf8] focus:ring-2 focus:ring-blue-200"/><button onClick={() => setMode('details')} className="rounded-xl bg-[#0967ff] px-5 py-3 text-sm font-black text-white">Confirm pin</button></div></div></div></div></div>
  return <div><PageHeading eyebrow="YOUR PLACES" title="Addresses & location" copy="Choose a saved place, or pin a new location for this booking." action="Add a new location" onAction={() => setMode('pin')}/><div className="mt-8 grid gap-7 xl:grid-cols-[.85fr_1.15fr]"><div className="space-y-4">{savedPlaces.map(place => <button key={place.address} onClick={() => setSelected(place.address)} className={`flex w-full items-center gap-4 rounded-2xl border p-5 text-left transition ${selected === place.address ? 'border-[#0967ff] bg-[#f3f8ff] shadow-lg shadow-blue-100' : 'border-[#e2eaf5] bg-white hover:border-blue-200'}`}><div className={`flex h-12 w-12 items-center justify-center rounded-xl ${selected === place.address ? 'bg-[#0967ff] text-white' : 'bg-[#f4f8fe] text-[#0967ff]'}`}><MapPin size={21}/></div><div className="flex-1"><p className="text-sm font-black">{place.label}</p><p className="mt-1 text-sm font-semibold text-[#74829a]">{place.detail}</p></div>{selected === place.address && <CheckCircle2 size={20} className="text-[#0967ff]"/>}</button>)}<button onClick={() => setMode('pin')} className="flex w-full items-center justify-center gap-2 rounded-2xl border border-dashed border-[#b9d0f5] bg-white py-4 text-sm font-black text-[#0967ff]"><Plus size={17}/> Add a new address</button>{params?.returnTo === 'booking-checkout' && <button onClick={() => finish(selected)} className="w-full rounded-xl bg-[#0967ff] py-3.5 text-sm font-black text-white shadow-lg shadow-blue-200">Use this location <Check size={16} className="ml-1 inline"/></button>}</div><div className="relative min-h-[400px] overflow-hidden rounded-[28px] bg-[#d9e9f8] shadow-sm"><img src="/assets/qatar-map-helpy-theme.png" alt="Map of Doha" className="absolute inset-0 h-full w-full object-cover opacity-80"/><div className="absolute inset-0 bg-gradient-to-t from-[#071b52]/20 via-transparent to-white/10"/><div className="absolute left-[48%] top-[43%] flex h-14 w-14 items-center justify-center rounded-full bg-[#0967ff] text-white shadow-2xl shadow-blue-500/50"><MapPin size={27} fill="currentColor"/></div><div className="absolute bottom-5 left-5 rounded-2xl bg-white p-4 shadow-xl"><p className="text-xs font-black uppercase tracking-[.12em] text-[#0967ff]">Selected location</p><p className="mt-1 text-sm font-black">{selected}</p><p className="mt-1 text-xs font-bold text-[#75839d]">Service availability is great here</p></div></div></div></div>
}

function LocationView({ navigate }: { navigate: (screen: Screen, params?: any) => void }) {
  const [selected, setSelected] = useState('Home')
  return <div><PageHeading eyebrow="YOUR PLACES" title="Addresses & location" copy="Set your preferred places to make every booking faster." action="Add address" onAction={() => navigate('addresses')}/><div className="mt-8 grid gap-7 xl:grid-cols-[.85fr_1.15fr]"><div className="space-y-4">{[{ name: 'Home', detail: 'Tower 19, West Bay, Doha', icon: Home }, { name: 'Work', detail: 'Lusail Boulevard, Lusail', icon: Landmark }].map(place => <button key={place.name} onClick={() => setSelected(place.name)} className={`flex w-full items-center gap-4 rounded-2xl border p-5 text-left transition ${selected === place.name ? 'border-[#0967ff] bg-[#f3f8ff] shadow-lg shadow-blue-100' : 'border-[#e2eaf5] bg-white hover:border-blue-200'}`}><div className={`flex h-12 w-12 items-center justify-center rounded-xl ${selected === place.name ? 'bg-[#0967ff] text-white' : 'bg-[#f4f8fe] text-[#0967ff]'}`}><place.icon size={21}/></div><div className="flex-1"><p className="text-sm font-black">{place.name}</p><p className="mt-1 text-sm font-semibold text-[#74829a]">{place.detail}</p></div>{selected === place.name && <CheckCircle2 size={20} className="text-[#0967ff]"/>}</button>)}<button onClick={() => navigate('addresses')} className="flex w-full items-center justify-center gap-2 rounded-2xl border border-dashed border-[#b9d0f5] bg-white py-4 text-sm font-black text-[#0967ff]"><Plus size={17}/> Add a new address</button></div><div className="relative min-h-[400px] overflow-hidden rounded-[28px] bg-[#d9e9f8] shadow-sm"><div className="absolute inset-0 opacity-70" style={{ backgroundImage: 'linear-gradient(30deg,transparent 47%,#ffffff 48%,#ffffff 52%,transparent 53%),linear-gradient(120deg,transparent 47%,#ffffff 48%,#ffffff 52%,transparent 53%)', backgroundSize: '120px 120px' }}/><div className="absolute left-[20%] top-[30%] h-32 w-32 rounded-full bg-[#9ed5fc]/70 blur-2xl"/><div className="absolute right-[18%] top-[18%] h-44 w-44 rounded-full bg-[#9de8d6]/50 blur-3xl"/><div className="absolute left-[48%] top-[43%] flex h-14 w-14 items-center justify-center rounded-full bg-[#0967ff] text-white shadow-2xl shadow-blue-500/50"><MapPin size={27} fill="currentColor"/></div><div className="absolute bottom-5 left-5 rounded-2xl bg-white p-4 shadow-xl"><p className="text-xs font-black uppercase tracking-[.12em] text-[#0967ff]">Selected location</p><p className="mt-1 text-sm font-black">{selected} · West Bay</p><p className="mt-1 text-xs font-bold text-[#75839d]">Service availability is great here</p></div></div></div></div>
}

function ReviewsView({ service, navigate }: { service: Service; navigate: (screen: Screen, params?: any) => void }) {
  const reviews = [['Mariam A.', 'Excellent attention to detail. My place felt completely refreshed.', '5.0', '2 days ago'], ['Omar K.', 'On time, polite and very professional. I would book again.', '5.0', '1 week ago'], ['Leila S.', 'Really good service and clear communication from start to finish.', '4.0', '2 weeks ago']]
  return <div><PageHeading eyebrow="COMMUNITY FEEDBACK" title={`${service.provider} reviews`} copy="Honest feedback from people who booked this provider." action="Book this service" onAction={() => navigate('service-detail', service)}/><div className="mt-8 grid gap-7 xl:grid-cols-[.65fr_1.35fr]"><aside className="rounded-[26px] bg-[#071b52] p-7 text-white"><p className="text-xs font-black uppercase tracking-[.14em] text-[#92d2ff]">Overall rating</p><div className="mt-5 flex items-end gap-3"><span className="text-6xl font-black tracking-[-.06em]">{service.rating}</span><div className="pb-2"><div className="flex text-amber-300">{[1,2,3,4,5].map(star => <Star key={star} size={18} fill="currentColor"/>)}</div><p className="mt-1 text-xs font-bold text-blue-100">Based on {service.reviews} reviews</p></div></div><div className="mt-8 space-y-3">{[5,4,3,2,1].map(rating => <div key={rating} className="flex items-center gap-3 text-xs font-bold"><span>{rating} <Star size={11} className="inline" fill="currentColor"/></span><div className="h-2 flex-1 overflow-hidden rounded-full bg-white/15"><div className="h-full rounded-full bg-amber-300" style={{ width: `${rating === 5 ? 82 : rating === 4 ? 13 : 5}%` }}/></div><span className="w-6 text-right text-blue-100">{rating === 5 ? 98 : rating === 4 ? 15 : 4}</span></div>)}</div></aside><div className="space-y-4">{reviews.map(review => <article key={review[0]} className="rounded-[23px] bg-white p-6 shadow-sm ring-1 ring-[#e3ebf6]"><div className="flex items-start gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-50 text-sm font-black text-[#0967ff]">{review[0][0]}</div><div className="flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-sm font-black">{review[0]}</p><span className="text-xs font-bold text-[#96a3b8]">{review[3]}</span></div><div className="mt-1 flex items-center gap-1 text-amber-500">{[1,2,3,4,5].map(star => <Star key={star} size={13} fill="currentColor"/>)}<span className="ml-1 text-xs font-black text-[#65738c]">{review[2]}</span></div></div></div><p className="mt-4 text-sm leading-7 text-[#66748e]">{review[1]}</p></article>)}</div></div></div>
}

function AccountView({ screen, navigate }: { screen: Screen; navigate: (screen: Screen, params?: any) => void }) {
  if (screen === 'wallet') return <WalletView navigate={navigate}/>
  if (screen === 'favorites') return <div><PageHeading eyebrow="SAVED FOR LATER" title="Your favourites" copy="The services and providers you want to keep close."/><div className="mt-8 grid gap-5 md:grid-cols-2 xl:grid-cols-3">{SERVICES.slice(0,3).map(service => <ServiceCard key={service.id} service={service} navigate={navigate}/>)}</div></div>
  if (screen === 'notifications') return <NotificationsView navigate={navigate}/>
  if (screen === 'addresses') return <LocationView navigate={navigate}/>
  return <div><PageHeading eyebrow="ACCOUNT" title="My profile" copy="Manage your personal details, preferences and Helpy account."/><div className="mt-8 grid gap-7 xl:grid-cols-[.8fr_1.2fr]"><aside className="rounded-[26px] bg-[#071b52] p-7 text-white"><div className="flex h-20 w-20 items-center justify-center rounded-[25px] bg-gradient-to-br from-[#67bcff] to-[#2d6cff] text-2xl font-black shadow-xl">SS</div><h2 className="mt-5 text-2xl font-black">Siraj Sayed</h2><p className="mt-1 text-sm font-bold text-blue-100">siraj@helpy.qa</p><div className="mt-7 border-t border-white/15 pt-6"><p className="text-xs font-black uppercase tracking-[.14em] text-[#91d4ff]">Helpy member since</p><p className="mt-2 text-sm font-black">August 2026</p></div></aside><div className="overflow-hidden rounded-[26px] bg-white shadow-sm ring-1 ring-[#e2ebf7]"><AccountRow icon={<UserRound size={19}/>} title="Personal details" text="Name, phone number and email" onClick={() => {}}/><AccountRow icon={<MapPin size={19}/>} title="Addresses" text="Home, work and saved places" onClick={() => navigate('addresses')}/><AccountRow icon={<Wallet size={19}/>} title="Wallet & payments" text="Saved cards and transaction history" onClick={() => navigate('wallet')}/><AccountRow icon={<Heart size={19}/>} title="Saved services" text="Providers and services you want to revisit" onClick={() => navigate('favorites')}/><AccountRow icon={<Bell size={19}/>} title="Notifications" text="Booking updates and preferences" onClick={() => navigate('notifications')}/><AccountRow icon={<Settings size={19}/>} title="Account settings" text="Privacy, language and support" onClick={() => navigate('contact-us')}/></div></div></div>
}

function WalletView({ navigate }: { navigate: (screen: Screen, params?: any) => void }) {
  return <div><PageHeading eyebrow="PAYMENTS" title="Your wallet" copy="Keep your payments safe, simple and ready for your next booking." action="Add payment method" onAction={() => {}}/><div className="mt-8 grid gap-7 xl:grid-cols-[.75fr_1.25fr]"><div className="rounded-[28px] bg-gradient-to-br from-[#0967ff] to-[#06348d] p-7 text-white shadow-xl shadow-blue-200"><div className="flex justify-between"><CreditCard size={27}/><span className="rounded-lg border border-white/20 px-2 py-1 text-[10px] font-black">VISA</span></div><p className="mt-12 text-xl font-black tracking-[.16em]">•••• 4821</p><div className="mt-7 flex justify-between text-xs font-bold text-blue-100"><span>SIRAJ SAYED</span><span>08/29</span></div></div><div className="rounded-[26px] bg-white shadow-sm ring-1 ring-[#e2ebf7]"><div className="flex items-center justify-between border-b border-[#e9eff7] p-6"><div><p className="text-lg font-black">Recent activity</p><p className="mt-1 text-sm font-semibold text-[#75839d]">Your latest payments and refunds</p></div><button onClick={() => navigate('orders')} className="text-xs font-black text-[#0967ff]">View bookings</button></div>{[['Scrubs Cleaning', 'General cleaning', '- QAR 160.00', '12 Sep'], ['Sparkle Auto Wash', 'Premium car wash', '- QAR 75.00', '06 Sep'], ['Helpy credit', 'Welcome offer', '+ QAR 20.00', '01 Sep']].map(item => <div key={item[0]} className="flex items-center gap-4 border-b border-[#eff3f8] px-6 py-5 last:border-0"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#f4f8fe] text-[#0967ff]"><CreditCard size={18}/></div><div className="flex-1"><p className="text-sm font-black">{item[0]}</p><p className="mt-1 text-xs font-bold text-[#7d8ba3]">{item[1]} · {item[3]}</p></div><p className={`text-sm font-black ${item[2].startsWith('+') ? 'text-emerald-500' : 'text-[#20304e]'}`}>{item[2]}</p></div>)}</div></div></div>
}

function NotificationsView({ navigate }: { navigate: (screen: Screen, params?: any) => void }) {
  const notifications: Array<{ title: string; body: string; time: string; Icon: LucideIcon }> = [{ title: 'Your booking is confirmed', body: 'Scrubs Cleaning will see you Friday at 10:00 AM.', time: 'Just now', Icon: CalendarDays }, { title: 'A deal you saved is ending soon', body: 'Get 20% off your Deep Cleaning booking today.', time: '2 hours ago', Icon: Sparkles }, { title: 'Welcome to Helpy', body: 'Explore your profile and set up your preferred addresses.', time: '1 day ago', Icon: Heart }]
  return <div><PageHeading eyebrow="KEEP UP TO DATE" title="Notifications" copy="The updates that matter, gathered in one calm place."/><div className="mt-8 overflow-hidden rounded-[26px] bg-white shadow-sm ring-1 ring-[#e2ebf7]">{notifications.map(({ title, body, time, Icon }, index) => <button key={title} onClick={() => index === 0 ? navigate('orders') : index === 1 ? navigate('deals') : navigate('profile')} className="flex w-full gap-4 border-b border-[#eaf0f7] p-6 text-left transition last:border-0 hover:bg-[#f9fbff]"><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-blue-50 text-[#0967ff]"><Icon size={20}/></div><div className="flex-1"><div className="flex flex-wrap justify-between gap-2"><p className="text-sm font-black">{title}</p><span className="text-xs font-bold text-[#99a6ba]">{time}</span></div><p className="mt-2 text-sm leading-6 text-[#73819a]">{body}</p></div></button>)}</div></div>
}

function InfoView({ screen, navigate }: { screen: Screen; navigate: (screen: Screen, params?: any) => void }) {
  const helpCards: Array<{ title: string; body: string; Icon: LucideIcon; action: () => void }> = [{ title: 'Message support', body: 'Get help with a booking or account.', Icon: MessageCircle, action: () => navigate('chat-thread', { name: 'Helpy Support' }) }, { title: 'Booking questions', body: 'Find clear answers before you book.', Icon: CalendarDays, action: () => navigate('orders') }, { title: 'Manage your account', body: 'Update details, payment and preferences.', Icon: Settings, action: () => navigate('profile') }]
  if (screen === 'contact-us') return <div><PageHeading eyebrow="HERE WHEN YOU NEED US" title="Help centre" copy="Tell us what you need—we’ll point you in the right direction."/><div className="mt-8 grid gap-5 md:grid-cols-3">{helpCards.map(({ title, body, Icon, action }) => <button key={title} onClick={action} className="rounded-[24px] bg-white p-6 text-left shadow-sm ring-1 ring-[#e2ebf7] transition"><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-blue-50 text-[#0967ff]"><Icon size={22}/></div><h2 className="mt-5 text-lg font-black">{title}</h2><p className="mt-2 text-sm leading-6 text-[#74829b]">{body}</p><span className="mt-5 inline-flex items-center gap-1 text-sm font-black text-[#0967ff]">Get help <ArrowRight size={15}/></span></button>)}</div><div className="mt-7 rounded-[26px] bg-[#071b52] p-7 text-white"><p className="text-xs font-black uppercase tracking-[.14em] text-[#9edbff]">Send us a message</p><div className="mt-5 grid gap-4 md:grid-cols-2"><input placeholder="What can we help with?" className="h-12 rounded-xl bg-white/10 px-4 text-sm font-bold outline-none placeholder:text-blue-200"/><button onClick={() => navigate('chat-thread', { name: 'Helpy Support' })} className="rounded-xl bg-white text-sm font-black text-[#0967ff]">Start a conversation</button></div></div></div>
  const title = screen === 'terms' ? 'Terms of service' : 'Privacy, clearly explained'
  const body = screen === 'terms' ? 'These terms explain how Helpy connects customers with independent service providers and how bookings work.' : 'Your information is treated with care. We only use what is needed to deliver a safe, helpful service experience.'
  return <div><PageHeading eyebrow="THE SMALL PRINT, MADE SIMPLE" title={title} copy={body}/><article className="mt-8 rounded-[26px] bg-white p-7 shadow-sm ring-1 ring-[#e2ebf7] sm:p-10"><div className="max-w-3xl space-y-7 text-sm leading-7 text-[#65738c]"><section><h2 className="text-xl font-black text-[#102044]">1. What this means for you</h2><p className="mt-3">Helpy makes it easier to discover, compare and book local services. We work hard to make every interaction clear, secure and useful.</p></section><section><h2 className="text-xl font-black text-[#102044]">2. Your choices</h2><p className="mt-3">You control your bookings, saved payment methods, communications and account information. You can update your preferences at any time.</p></section><section><h2 className="text-xl font-black text-[#102044]">3. A dependable experience</h2><p className="mt-3">We expect providers to meet the quality standards our community deserves. If something feels off, our support team is here to help.</p></section></div></article></div>
}

function PageHeading({ eyebrow, title, copy, action, onAction }: { eyebrow: string; title: string; copy: string; action?: string; onAction?: () => void }) {
  return <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-[11px] font-black uppercase tracking-[.16em] text-[#0967ff]">{eyebrow}</p><h1 className="mt-2 text-3xl font-black tracking-[-.045em] text-[#102044] sm:text-4xl">{title}</h1><p className="mt-3 max-w-2xl text-sm leading-7 font-semibold text-[#6d7b94]">{copy}</p></div>{action && <button onClick={onAction} className="w-fit rounded-xl bg-[#0967ff] px-4 py-3 text-sm font-black text-white shadow-md shadow-blue-200 transition hover:bg-[#0759df]">{action} <ArrowRight size={15} className="ml-1 inline"/></button>}</div>
}

function SectionTitle({ eyebrow, title, action, onAction }: { eyebrow: string; title: string; action?: string; onAction?: () => void }) {
  return <div className="flex items-end justify-between gap-4"><div><p className="text-[10px] font-black uppercase tracking-[.16em] text-[#0967ff]">{eyebrow}</p><h2 className="mt-1 text-2xl font-black tracking-[-.04em]">{title}</h2></div>{action && <button onClick={onAction} className="mb-1 text-sm font-black text-[#0967ff]">{action} <ArrowRight size={15} className="ml-1 inline"/></button>}</div>
}

function ServiceCard({ service, navigate }: { service: Service; navigate: (screen: Screen, params?: any) => void }) {
  const [saved, setSaved] = useState(false)
  const openDetails = () => navigate('service-detail', service)
  return <article
    onClick={openDetails}
    onKeyDown={event => {
      if (event.target !== event.currentTarget) return
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault()
        openDetails()
      }
    }}
    role="link"
    tabIndex={0}
    aria-label={`View details for ${service.name} by ${service.provider}`}
    className="group cursor-pointer overflow-hidden rounded-[23px] bg-white shadow-sm ring-1 ring-[#e2ebf7] transition focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-blue-200"
  ><div className="relative h-44 overflow-hidden"><img src={service.image} alt="" loading="lazy" className="h-full w-full object-cover transition duration-500"/><div className="absolute inset-0 bg-gradient-to-t from-[#071331]/50 via-transparent to-transparent"/><button onClick={event => { event.stopPropagation(); setSaved(value => !value) }} className="absolute right-3 top-3 flex h-9 w-9 items-center justify-center rounded-xl bg-white/90 text-[#102044] shadow-md" aria-label="Save service"><Heart size={17} fill={saved ? '#ff5c7a' : 'none'} className={saved ? 'text-[#ff5c7a]' : ''}/></button><span className="absolute bottom-3 left-3 rounded-lg bg-white/95 px-2.5 py-1 text-[10px] font-black text-[#102044]">{service.category}</span></div><div className="p-5"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="truncate text-lg font-black">{service.name}</p><p className="mt-1 truncate text-sm font-bold text-[#77859d]">{service.provider}</p></div><span className="flex shrink-0 items-center gap-1 rounded-lg bg-amber-50 px-2 py-1 text-xs font-black text-amber-600"><Star size={12} fill="currentColor"/>{service.rating}</span></div><div className="mt-5 flex items-center justify-between"><p className="text-sm font-black text-[#0967ff]">from QAR {service.price}</p><span className="rounded-xl bg-[#0967ff] px-3.5 py-2.5 text-xs font-black text-white transition group-hover:bg-[#0759df]">View details</span></div></div></article>
}

function OfferPanel({ title, text, image, onClick }: { title: string; text: string; image: string; onClick: () => void }) {
  return <button onClick={onClick} className="group relative min-h-[170px] overflow-hidden rounded-[22px] text-left shadow-sm"><img src={image} alt="" className="absolute inset-0 h-full w-full object-cover transition duration-500"/><div className="absolute inset-0 bg-gradient-to-r from-[#071b52]/90 via-[#071b52]/55 to-transparent"/><div className="relative max-w-[210px] p-5 text-white"><span className="rounded-full bg-[#dfff2d] px-2 py-1 text-[10px] font-black text-[#253600]">LIMITED OFFER</span><p className="mt-4 text-lg font-black leading-5">{title}</p><p className="mt-2 text-xs leading-5 font-semibold text-blue-100">{text}</p></div></button>
}

function DetailCheck({ title, text }: { title: string; text: string }) { return <div className="rounded-2xl bg-[#f6f9fe] p-4"><CheckCircle2 size={19} className="text-[#0967ff]"/><p className="mt-3 text-sm font-black">{title}</p><p className="mt-1 text-xs leading-5 font-semibold text-[#78869e]">{text}</p></div> }
function CheckoutBlock({ number, title, action, onAction, children }: { number: string; title: string; action?: string; onAction?: () => void; children: ReactNode }) { return <section className="rounded-[24px] bg-white p-6 shadow-sm ring-1 ring-[#e2ebf7]"><div className="mb-5 flex items-center justify-between"><div className="flex items-center gap-3"><span className="flex h-7 w-7 items-center justify-center rounded-lg bg-blue-50 text-xs font-black text-[#0967ff]">{number}</span><h2 className="text-lg font-black">{title}</h2></div>{action && <button onClick={onAction} className="text-xs font-black text-[#0967ff]">{action}</button>}</div>{children}</section> }
function SummaryInfo({ icon, label, value }: { icon: ReactNode; label: string; value: string }) { return <div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-blue-50 text-[#0967ff]">{icon}</div><div><p className="text-[10px] font-black uppercase tracking-[.12em] text-[#98a5ba]">{label}</p><p className="mt-1 text-xs font-black text-[#35435e]">{value}</p></div></div> }
function StatusBadge({ status }: { status: string }) { const style = status === 'Completed' ? 'bg-emerald-50 text-emerald-600' : status === 'In Progress' ? 'bg-amber-50 text-amber-600' : 'bg-blue-50 text-[#0967ff]'; return <span className={`inline-flex rounded-full px-3 py-1.5 text-xs font-black ${style}`}>{status}</span> }
function AccountRow({ icon, title, text, onClick }: { icon: ReactNode; title: string; text: string; onClick: () => void }) { return <button onClick={onClick} className="flex w-full items-center gap-4 border-b border-[#edf1f7] px-6 py-5 text-left last:border-0 transition hover:bg-[#f9fbff]"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-50 text-[#0967ff]">{icon}</div><div className="flex-1"><p className="text-sm font-black">{title}</p><p className="mt-1 text-xs font-bold text-[#7c8aa2]">{text}</p></div><ChevronRight size={18} className="text-[#a8b3c5]"/></button> }
function EmptyScreen({ title, body, action, onClick }: { title: string; body: string; action: string; onClick: () => void }) { return <div className="mt-7 rounded-[26px] bg-white py-16 text-center shadow-sm ring-1 ring-[#e2ebf7]"><Inbox size={34} className="mx-auto text-[#8ba4c8]"/><h2 className="mt-4 text-lg font-black">{title}</h2><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-[#74829b]">{body}</p><button onClick={onClick} className="mt-5 text-sm font-black text-[#0967ff]">{action}</button></div> }

function asService(value: any): Service { if (value?.provider && value?.name) return { ...SERVICES[0], ...value, id: value.id || 'selected', category: value.category || 'Home services', rating: value.rating || '4.8', reviews: value.reviews || '120', image: value.image || value.heroImg || SERVICES[0].image, description: value.description || SERVICES[0].description, providerBg: value.providerBg || 'bg-blue-500', providerEmoji: value.providerEmoji || 'HP' }; return SERVICES[0] }
